package com.tracksphere.interfaces.rest;
import com.tracksphere.application.auth.AuthService; import com.tracksphere.application.auth.dto.*; import io.swagger.v3.oas.annotations.Operation; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") @RequiredArgsConstructor public class AuthController { private final AuthService service; @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) @Operation(summary="Register a user") public AuthResponse register(@Valid @RequestBody RegisterRequest request){return service.register(request);}@PostMapping("/login") @Operation(summary="Authenticate with email and password") public AuthResponse login(@Valid @RequestBody LoginRequest request){return service.login(request);}@PostMapping("/refresh") @Operation(summary="Rotate a refresh token") public AuthResponse refresh(@Valid @RequestBody RefreshTokenRequest request){return service.refresh(request);} }
